function valid(item,board){
 const refs=item.refs.filter(r=>board.elements.some(e=>e.name===r));
 const nets=item.nets.filter(n=>board.nets.some(x=>x.name===n));
 return {...item,refs,nets};
}
export function filterExamplesFor(board){return (actualByBoard[board.id]||[]).map(x=>valid(x,board)).filter(x=>x.refs.length&&x.nets.length);}

