 if(kind==='highpass')return common+'<text x="18" y="28">PASO ALTO / ACOPLAMIENTO</text><path class="w" d="M30 85H95"/><path class="c" d="M95 62v46m18-46v46"/><path class="w" d="M113 85H260"/><path class="w" d="M260 85v21m0 41v15"/><path class="c" d="M260 106l-11 7 22 9 -22 9 22 9 -11 7"/><path class="w" d="M260 85H370"/><text x="20" y="75">IN</text><text x="378" y="90">OUT</text><text x="242" y="180">GND</text><text x="93" y="48">C</text><text x="288" y="128">R / carga</text></svg>';
 if(kind==='bandpass')return common+'<text x="18" y="28">PASO BANDA · RC EN CASCADA</text><path class="w" d="M28 85H78"/><path class="c" d="M78 62v46m18-46v46"/><path class="w" d="M96 85H138V104M138 146v15M138 85H187"/><path class="c" d="M138 104l-10 7 20 9 -20 9 20 9 -10 8 M187 85l8-12 9 24 9-24 9 12"/><path class="w" d="M222 85H275V121M275 139v22M275 85H360"/><path class="c" d="M255 121h40m-40 18h40"/><text x="18" y="75">IN</text><text x="364" y="90">OUT</text><text x="68" y="45">C1</text><text x="113" y="176">R1</text><text x="187" y="52">R2</text><text x="302" y="134">C2</text><path class="a" d="M410 135C435 135 438 60 465 60s30 75 55 75"/><text x="416" y="158">fL  banda  fH</text></svg>';
 if(kind==='active')return common+'<text x="18" y="28">FILTRO ACTIVO · RC + BÚFER</text><path class="w" d="M25 85H80M128 85H215V78H243M303 90H390"/><path class="c" d="M80 85l9-12 10 24 10-24 10 24 9-12 M190 85v34m-20 0h40m-40 16h40"/><path class="w" d="M190 135v27"/><path class="a" d="M243 58L303 90 243 122zM303 90V150H229V107H243"/><text x="20" y="73">IN</text><text x="397" y="94">OUT</text><text x="90" y="50">R</text><text x="215" y="128">C</text><text x="250" y="82">+</text><text x="250" y="113">−</text><text x="245" y="48">OP-AMP</text><text x="178" y="180">GND</text></svg>';
 if(kind==='lc')return common+'<text x="18" y="28">SALIDA BUCK · FILTRO LC</text><path class="w" d="M25 85H90"/><path class="c" d="M90 85c12-32 24 32 36 0s24 32 36 0 24 32 36 0"/><path class="w" d="M198 85H285"/><path class="c" d="M285 85v38m-22 0h44m-44 14h44"/><path class="w" d="M285 137v25M285 85H390"/><text x="20" y="74">SW</text><text x="400" y="90">RAIL DC</text><text x="137" y="54">L</text><text x="315" y="132">C</text></svg>';
 return common+'<text x="18" y="28">DESACOPLO / FILTRADO DE ALIMENTACIÓN</text><path class="w" d="M40 85H300"/><path class="c" d="M170 85v38m-22 0h44m-44 14h44"/><path class="w" d="M170 137v25"/><text x="30" y="75">RAIL</text><text x="308" y="90">IC / carga</text><text x="198" y="132">C</text><text x="154" y="180">GND</text></svg>';
