export function mountFilterExplorer(api,host,{explorer,openPlan}={}){
 const panel=document.createElement('details');panel.className='filterExplorer';
 panel.innerHTML='<summary>Filtros de esta placa <span>real ↔ esquema ↔ PCB ↔ señal</span></summary><div class="filterIntro"><p>Selecciona una topología para ver <b>qué componentes la forman, qué atenúa y por qué está ahí</b>. “Real en esta placa” significa que la conexión puede comprobarse en los datos CAD/modelo cargado; los ejemplos didácticos no se presentan como hardware existente.</p></div><div class="filterActual"></div><details class="filterTeaching"><summary>Comparar con los 4 filtros fundamentales</summary><div class="filterTeachingGrid"></div></details><div class="filterDetail" hidden></div>';
 host.append(panel);const $=s=>panel.querySelector(s);let currentId='';
 function badge(board){return board.educational||board.representative?'TOPOLOGÍA DEL MODELO DIDÁCTICO':'REAL EN ESTA PLACA';}
 function cards(items,actual=true){return items.map(x=>'<button class="filterCard" data-filter="'+esc(x.id)+'"><span class="filterBadge">'+esc(actual?badge(api.board()):x.badge)+'</span><b>'+esc(x.title)+'</b><small>'+esc(x.summary)+'</small></button>').join('');}
 function show(item,isActual){
  const b=api.board(),box=$('.filterDetail');box.hidden=false;box.innerHTML='<div class="filterDetailHead"><div><span class="filterBadge">'+esc(isActual?badge(b):item.badge)+'</span><h3>'+esc(item.title)+'</h3></div><span>'+esc(item.kind.toUpperCase())+'</span></div><div class="filterDetailGrid"><div class="filterDiagram">'+diagram(item.kind)+'</div><div><h4>¿Por qué está aquí?</h4><p>'+esc(item.why)+'</p><p class="filterFormula">'+esc(item.formula)+'</p><h4>Qué mirar con el osciloscopio</h4><p>'+esc(item.check)+'</p></div></div>';
  if(isActual){
   box.innerHTML+='<div class="filterRefs"><b>Componentes implicados</b>'+item.refs.map(r=>'<button data-filter-ref="'+esc(r)+'">'+esc(r)+'</button>').join('')+'</div><div class="filterRefs"><b>Redes relacionadas</b>'+item.nets.map(n=>'<button data-filter-net="'+esc(n)+'">'+esc(n)+'</button>').join('')+'</div><div class="filterActions"><button class="filterSchema">Resaltar en esquema</button><button class="filterMap">Abrir mapa PCB</button></div>';
   box.querySelectorAll('[data-filter-ref]').forEach(x=>x.onclick=()=>api.focus(x.dataset.filterRef));
   box.querySelectorAll('[data-filter-net]').forEach(x=>x.onclick=()=>api.net(x.dataset.filterNet));
   box.querySelector('.filterSchema').onclick=()=>explorer?.highlight({refs:item.refs,nets:item.nets,title:item.title});
   box.querySelector('.filterMap').onclick=()=>openPlan?.({block:'off',shared:false,net:item.nets[0]||'',filterRefs:item.refs,filterNets:item.nets});
   api.filter?.(item);if(item.nets[0])api.net(item.nets[0]);api.focusGroup?.(item.refs);explorer?.highlight({refs:item.refs,nets:item.nets,title:item.title});
  }
  box.scrollIntoView({behavior:'smooth',block:'nearest'});
 }
 function wire(){
  const actual=filterExamplesFor(api.board()),all=[...actual,...filterTeaching];
  panel.querySelectorAll('[data-filter]').forEach(btn=>btn.onclick=()=>{const item=all.find(x=>x.id===btn.dataset.filter);if(item)show(item,actual.some(x=>x.id===item.id));});
 }
 function refresh(){const b=api.board();if(!b)return;if(currentId===b.id&&$('.filterActual').children.length)return;currentId=b.id;const actual=filterExamplesFor(b);$('.filterActual').innerHTML='<div class="filterSectionHead"><b>Encontrados en '+esc(b.title)+'</b><span>'+actual.length+'</span></div>'+(actual.length?'<div class="filterGrid">'+cards(actual,true)+'</div>':'<p class="filterEmpty">No hay una topología de filtro suficientemente demostrable en los datos de esta placa. No se inventa una: usa los ejemplos didácticos de abajo para aprender a reconocerla.</p>');$('.filterTeachingGrid').innerHTML=cards(filterTeaching,false);$('.filterDetail').hidden=true;$('.filterDetail').replaceChildren();wire();}
 refresh();return {refresh,open(){panel.open=true;refresh();}};
}
